<?php
if(session_status()===PHP_SESSION_NONE)session_start();require_once '../includes/config.php';require_once '../includes/database.php';require_once '../includes/auth.php';$db=new Database();$auth=new Auth($db);$auth->requireRole(['supervisor','system_admin']);$pdo=$db->getConnection();$rows=[];try{$rows=$pdo->query("SELECT b.baggage_code,b.status,b.weight,f.flight_number,u.full_name,b.updated_at FROM baggage b JOIN flights f ON b.flight_id=f.id JOIN users u ON b.passenger_id=u.id ORDER BY b.updated_at DESC LIMIT 100")->fetchAll();}catch(Throwable $e){}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inspection Reports</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container py-5"><h2>Quality & Inspection Reports</h2><p class="text-muted">Operational review of recent baggage records.</p><table class="table table-striped bg-white"><thead><tr><th>Baggage</th><th>Passenger</th><th>Flight</th><th>Status</th><th>Weight</th><th>Updated</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['baggage_code'])?></td><td><?=htmlspecialchars($r['full_name'])?></td><td><?=htmlspecialchars($r['flight_number'])?></td><td><?=htmlspecialchars($r['status'])?></td><td><?=htmlspecialchars($r['weight'])?></td><td><?=htmlspecialchars($r['updated_at'])?></td></tr><?php endforeach;?></tbody></table></div></body></html>